import{_ as s,C as n,o as r,c as o,j as t,a as i,E as h,a6 as c}from"./chunks/framework.CCKCzdWs.js";const l="/diagrams/uncovered-changes.svg",d="/screenshots/uncovered-changes.png",w=JSON.parse('{"title":"Uncovered changes in pull requests","description":"The files a pull request changed that no test observably reaches, and the changed lines no suite ran, posted on the pull request as a comment section and a commit status, with warn-only gate flags.","frontmatter":{"title":"Uncovered changes in pull requests","description":"The files a pull request changed that no test observably reaches, and the changed lines no suite ran, posted on the pull request as a comment section and a commit status, with warn-only gate flags.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/uncovered-changes.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/uncovered-changes.html"}],["meta",{"property":"og:title","content":"Uncovered changes in pull requests | Piwi for Playwright"}],["meta",{"property":"og:description","content":"The files a pull request changed that no test observably reaches, and the changed lines no suite ran, posted on the pull request as a comment section and a commit status, with warn-only gate flags."}]]},"headers":[],"relativePath":"features/uncovered-changes.md","filePath":"features/uncovered-changes.md","lastUpdated":1794347800000}'),g={name:"features/uncovered-changes.md"};function p(u,e,m,f,v,k){const a=n("Needs");return r(),o("div",null,[e[0]||(e[0]=t("h1",{id:"uncovered-changes-in-pull-requests",tabindex:"-1"},[i("Uncovered changes in pull requests "),t("a",{class:"header-anchor",href:"#uncovered-changes-in-pull-requests","aria-label":'Permalink to "Uncovered changes in pull requests"'},"​")],-1)),h(a,{reporter:"",scm:""}),e[1]||(e[1]=c('<p>A pull request that changes <code>server/api/orders/[id].patch.ts</code> while no test ever requests that route passes CI and proves nothing about the change. When a run finishes, Piwi joins the files its change touched to the tests that <a href="/guide/concepts.html#reach">observably reach</a> them, and names the changed files nothing reaches: the <strong>uncovered changes</strong>. Each one is a <em>changed, unreached</em> <a href="/features/scenario-gaps.html">scenario gap</a>. Its draft starts from the route or page the file serves, or the nearest one a test reaches under the same path, with that test named. When the head commit has <a href="/features/combined-coverage.html">combined coverage</a>, the same section counts the changed lines too, and names those no suite ran, in every file.</p><figure><img src="'+l+`" alt="A pull-request run&#39;s changed files are joined to the tests that reach them; each is reached, an uncovered change (a gap), or not counted, with the reason; the result goes to the pull request"></figure><h2 id="one-rule-for-every-changed-file" tabindex="-1">One rule for every changed file <a class="header-anchor" href="#one-rule-for-every-changed-file" aria-label="Permalink to &quot;One rule for every changed file&quot;">​</a></h2><p>The comment, its commit status, the gate, the MCP tool and the <em>changed, unreached</em> detector read one rule. A changed file is:</p><table tabindex="0"><thead><tr><th>Reach</th><th>When</th><th>Counted</th></tr></thead><tbody><tr><td><strong>Reached</strong></td><td>a test of this run reached it, or a suite of the head commit&#39;s coverage ran one of its changed lines</td><td>yes</td></tr><tr><td><strong>Reached earlier</strong></td><td>no test of this run did, but a test of the project&#39;s last 30 runs did: a run narrowed by a <a href="/features/test-selection.html">selection</a>, not a missing test</td><td>yes</td></tr><tr><td><strong>Unreached</strong></td><td>Piwi can observe the file, and nothing above reached it: an <strong>uncovered change</strong>, and a <em>changed, unreached</em> gap</td><td>yes</td></tr><tr><td><strong>Not observable</strong></td><td>nothing maps the file to a test, so nothing can be said either way</td><td>no</td></tr><tr><td><strong>Out of scope</strong></td><td>the project&#39;s <a href="/features/combined-coverage.html#the-coverage-scope">coverage scope</a> leaves it out: tests, build output and generated code by default</td><td>no</td></tr><tr><td><strong>Deleted</strong></td><td>the change removed it</td><td>no</td></tr></tbody></table><p>A test reaches a file when it:</p><ul><li>requested a route or visited a page the file serves, matched by the framework&#39;s file naming (<code>server/api/**</code>, <code>server/routes/**</code>, Nuxt <code>pages/**</code>);</li><li>ran a step whose locator is written in the file (a page object, a helper);</li><li>executed one of the file&#39;s functions, with <a href="/features/code-reach.html">code reach</a> on.</li></ul><p>Piwi can observe a file when one of these could happen to it, or when the head commit&#39;s coverage counts its changed lines. A skipped test reaches nothing. A <em>changed, unreached</em> gap closes when a later diff no longer counts its file as uncovered, or when the Test Map&#39;s next recompute finds it reached or out of scope; an accepted one closes only once a test reaches the file.</p><p>Before the pull request, the <a href="./editor-coverage.html#uncovered-changes">editor extensions</a> mark the lines of an uncovered change of a page or a server route in the file itself, by a rule of their own: no coverage scope, no window of runs, and a page counts as reached only when a test&#39;s locator acted on it.</p><p>The diff comes from the <a href="/guide/source-control.html">source control</a> connection. A run of a pull request is compared with the branch it merges into, so every push reports the whole pull request: the one its CI names, else the one open on its branch, so a push-triggered workflow reads its pull request too. Any other run is compared with the commit of the last passing run. A public repository is read without a token, so its uncovered changes and their gaps appear in Piwi, though nothing is posted; a private one needs a <a href="/guide/source-control.html#set-the-token">token</a>. With no diff, nothing appears.</p><h2 id="on-the-pull-request" tabindex="-1">On the pull request <a class="header-anchor" href="#on-the-pull-request" aria-label="Permalink to &quot;On the pull request&quot;">​</a></h2><p>With <a href="/features/pr-feedback.html">pull-request feedback</a> turned on, the comment gains an <strong>Uncovered changes</strong> section. The uncovered changes come first, grouped by ticket (read from the commit messages and the pull request):</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">#### 🟣 Uncovered changes · 3 of 7 files · 2 tickets</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Changed files no test reached, in this run or the last 30 runs. Observed reach, not instrumented coverage.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**PROJ-418**</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \`server/api/orders/[id].patch.ts\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> · changed (+41 −3) · 0 tests in 30 runs</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  → [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">open its gap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">https://piwi.example.com/projects/4?tab=coverage&amp;gap=31</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">): </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Accept**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> copies a draft test</span></span></code></pre></div><p>When the head commit has <a href="/features/combined-coverage.html">combined coverage</a>, the section also counts the change&#39;s lines that can run (its patch coverage), and names the changed lines no suite ran in the files a test did reach: a test visiting a file is not a test running the change.</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Patch coverage 82.9%**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 34 of the 41 changed lines ran (unit 28, end to end 19), at </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`a1b2c3d\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Changed lines no suite ran**</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \`api/Orders/OrderService.cs\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> · 7 of 12 ran · not run: 14 to 18, 40</span></span></code></pre></div><p>The section ends with what it did not count: <em>Not counted: 2 files Piwi cannot observe, 1 file outside the coverage scope.</em></p><p>Three more detectors read the whole pull request at each run: an error status a route&#39;s handler gains that no run answered with, a control a page gains, and a title no test&#39;s words match (<a href="/reference/gap-detectors.html#detectors">the detectors</a>). Their gaps carry the pull request&#39;s number, close when a later run no longer raises them, and the section counts them with a link to the pull request&#39;s gaps, where the change-coverage status leads too.</p><figure><img src="`+d+'" alt="The Uncovered changes section of a pull-request comment"><figcaption>Patch coverage, the changed files no test reaches, and the changed lines no suite ran.</figcaption></figure><p>A coverage report uploaded for the commit after the comment, or the run&#39;s own coverage arriving after it, posts the comment again a few seconds later; a later push&#39;s comment is never overwritten by an earlier commit&#39;s.</p><p>When commit statuses are on too, a second status joins the run&#39;s own: <code>piwi/tests/change-coverage</code> with the default status context, described as <em>3 of 7 changed files no test reached</em>, with the patch coverage when there is one. It is always <strong>success</strong>, so it informs a reviewer without blocking the merge, and it leads to the pull request&#39;s gaps on the Coverage tab.</p><p>The files no test reached are the Test Map&#39;s part: they are left out while the <em>changed, unreached</em> detector is <a href="/features/scenario-gaps.html#triage">muted</a> on the project, or where the Test Map is declined. The changed lines are coverage&#39;s part and stay either way.</p><h2 id="from-an-agent" tabindex="-1">From an agent <a class="header-anchor" href="#from-an-agent" aria-label="Permalink to &quot;From an agent&quot;">​</a></h2><p>The <a href="/reference/mcp-tools.html#get_change_coverage"><code>get_change_coverage</code></a> MCP tool returns the same join for a run or for an explicit base and head commit, grouped by ticket, without recording anything: each file&#39;s <code>reach</code>, its <code>lines</code> when the coverage counts them, and the files not counted. The <a href="/features/agent-skills.html">write-the-missing-test</a> skill takes it from there. The REST endpoint is in the <a href="https://piwitests.dev/demo/settings/api" target="_blank" rel="noreferrer">API docs</a>.</p><h2 id="the-gate-flags" tabindex="-1">The gate flags <a class="header-anchor" href="#the-gate-flags" aria-label="Permalink to &quot;The gate flags&quot;">​</a></h2><p>Two flags of <a href="/guide/ci.html#blocking-a-merge"><code>piwi gate</code></a> read the same rule, one per form:</p><ul><li><code>--max-uncovered-changes &lt;n&gt;</code> warns when more than <code>n</code> changed files are uncovered changes (the file form);</li><li><code>--min-patch-coverage &lt;percent&gt;</code> warns when fewer of the changed lines ran, or when the head commit&#39;s coverage names none of them (the line form). Run it after the unit-test jobs uploaded their reports.</li></ul><p>Both are <strong>warn-only</strong>: they never change the verdict or the exit code, because the numbers inform rather than prove. The first names up to five of the files, and a stored evaluation keeps its warnings. Either warns too when the run has no source control diff to count. Without them, the gate ignores uncovered changes.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Observed reach, then lines.</strong> Without coverage, a reached file may still hide an untested branch; with it, the changed lines no suite ran name it. An unreached file may be dead code.</li><li><strong>Naming conventions.</strong> Files map to routes and pages through Nitro and Nuxt file naming; other frameworks rely on locators, code reach and coverage, so without those more of their files are <em>not observable</em> and not counted.</li><li><strong>Ten files listed.</strong> The comment names at most ten files per list and counts the rest.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/scenario-gaps.html">Scenario gaps &amp; the Test Map</a>: the other gaps, and triage</li><li><a href="/features/combined-coverage.html">Combined coverage</a>: the coverage the changed lines are counted on</li><li><a href="/features/pr-feedback.html">Pull-request feedback</a>: the comment this section joins</li><li><a href="/guide/source-control.html">Source control</a>: the token that provides the diff</li><li><a href="/reference/cli.html#gate">Piwi CLI: gate</a>: every gate flag</li></ul>',31))])}const y=s(g,[["render",p]]);export{w as __pageData,y as default};
